class TaskDetailScreen extends StatefulWidget { const TaskDetailScreen({super.key,required this.controller,required this.task});final WorkspaceController controller;final WorkspaceTask task;@override State<TaskDetailScreen> createState()=>_TaskDetailState(); }
class _TaskDetailState extends State<TaskDetailScreen>{late WorkspaceTask task=widget.task;Future<void> action(Future<WorkspaceTask?> Function() fn)async{final next=await fn();if(next!=null&&mounted)setState(()=>task=next);}@override Widget build(BuildContext context){final run=task.run;final terminal={WorkStatus.completed,WorkStatus.failed,WorkStatus.cancelled}.contains(task.status);return Scaffold(appBar:AppBar(title:const Text('Task detail')),body:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text(task.title,style:Theme.of(context).textTheme.titleLarge)),_StatusChip(task.status)]),const SizedBox(height:8),Text(task.prompt,style:Theme.of(context).textTheme.bodyMedium),const SizedBox(height:16),Wrap(spacing:8,children:[if(!terminal)OutlinedButton.icon(onPressed:()=>action(()=>widget.controller.cancelTask(task.id)),icon:const Icon(Icons.stop),label:const Text('Cancel')),if(task.status==WorkStatus.failed||task.status==WorkStatus.cancelled)FilledButton.icon(onPressed:()=>action(()=>widget.controller.resumeTask(task.id)),icon:const Icon(Icons.refresh),label:const Text('Resume'))]),const Divider(height:32),Text('Execution trace',style:Theme.of(context).textTheme.titleMedium),if(run==null||run.steps.isEmpty)const _Empty(icon:Icons.timeline,title:'No trace available',text:'Execution steps will appear when the run begins.')else ...run.steps.asMap().entries.map((entry)=>_TimelineStep(step:entry.value,index:entry.key+1,last:entry.key==run.steps.length-1)),if(run?.result case final result?)...[const Divider(height:32),Text('Result',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:8),SelectableText(result)] ]));}}

