class WorkspaceResourcesScreen extends StatefulWidget {const WorkspaceResourcesScreen({super.key,required this.controller});final WorkspaceController controller;@override State<WorkspaceResourcesScreen> createState()=>_ResourcesState();}
class _ResourcesState extends State<WorkspaceResourcesScreen> with SingleTickerProviderStateMixin{late final tabs=TabController(length:2,vsync:this);final memory=TextEditingController(),task=TextEditingController(),path=TextEditingController();@override void dispose(){tabs.dispose();memory.dispose();task.dispose();path.dispose();super.dispose();}@override Widget build(BuildContext context){final c=widget.controller;return Column(children:[TabBar(controller:tabs,tabs:const [Tab(text:'Files'),Tab(text:'Memory')]),Expanded(child:TabBarView(controller:tabs,children:[_files(c),_memory(c)]))]);}Widget _files(WorkspaceController c)=>ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:TextField(controller:path,decoration:const InputDecoration(border:OutlineInputBorder(),labelText:'Local file path'))),const SizedBox(width:8),IconButton.filled(tooltip:'Upload',onPressed:c.mutating?null:(){if(path.text.trim().isNotEmpty)c.uploadFile(path.text.trim());},icon:const Icon(Icons.upload))]),const SizedBox(height:16),if(c.files.isEmpty)const _Empty(icon:Icons.folder_open,title:'No files',text:'Upload a file to this workspace.')else ...c.files.map((f)=>ListTile(leading:const Icon(Icons.insert_drive_file_outlined),title:Text(f.name),subtitle:Text('${_bytes(f.sizeBytes)} · ${f.contentType}'),trailing:PopupMenuButton<String>(onSelected:(v)=>v=='download'?c.repository.downloadFile(f):c.deleteFile(f.id),itemBuilder:(_)=>const [PopupMenuItem(value:'download',child:Text('Download')),PopupMenuItem(value:'delete',child:Text('Delete'))])))]);Widget _memory(WorkspaceController c)=>ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:task,decoration:const InputDecoration(border:OutlineInputBorder(),labelText:'Task ID')),const SizedBox(height:8),TextField(controller:memory,minLines:2,maxLines:4,decoration:const InputDecoration(border:OutlineInputBorder(),labelText:'Memory')),const SizedBox(height:8),FilledButton.icon(onPressed:c.mutating?null:(){if(task.text.trim().isNotEmpty&&memory.text.trim().isNotEmpty){c.addMemory(task.text.trim(),memory.text.trim());memory.clear();}},icon:const Icon(Icons.add),label:const Text('Add memory')),const SizedBox(height:16),if(c.memories.isEmpty)const _Empty(icon:Icons.psychology_outlined,title:'No memories',text:'Add durable task context.')else ...c.memories.map((m)=>ListTile(leading:const Icon(Icons.psychology_outlined),title:Text(m.content,maxLines:2,overflow:TextOverflow.ellipsis),subtitle:Text('${m.sourceType} · ${m.taskId}'),trailing:IconButton(tooltip:'Delete',icon:const Icon(Icons.delete_outline),onPressed:()=>c.deleteMemory(m.id))))]);}

class _TimelineStep extends StatelessWidget{const _TimelineStep({required this.step,required this.index,required this.last});final RunStep step;final int index;final bool last;@override Widget build(BuildContext context)=>IntrinsicHeight(child:Row(crossAxisAlignment:CrossAxisAlignment.stretch,children:[SizedBox(width:32,child:Column(children:[CircleAvatar(radius:12,child:Text('$index',style:const TextStyle(fontSize:11))),if(!last)Expanded(child:Container(width:1,color:Theme.of(context).dividerColor))])),const SizedBox(width:10),Expanded(child:Padding(padding:const EdgeInsets.only(bottom:20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(step.type.replaceAll('_',' '),style:Theme.of(context).textTheme.labelLarge),Text(step.summary),Text(_when(step.createdAt),style:Theme.of(context).textTheme.bodySmall)]))) ]));}
class _StatusIcon extends StatelessWidget{const _StatusIcon(this.value);final WorkStatus value;@override Widget build(BuildContext context)=>CircleAvatar(backgroundColor:_color(context,value).withValues(alpha:.14),child:Icon(value==WorkStatus.completed?Icons.check:value==WorkStatus.failed?Icons.error_outline:value==WorkStatus.cancelled?Icons.stop:Icons.schedule,color:_color(context,value)));}
class _StatusChip extends StatelessWidget{const _StatusChip(this.value);final WorkStatus value;@override Widget build(BuildContext context)=>Chip(label:Text(_status(value)),backgroundColor:_color(context,value).withValues(alpha:.14));}
class _Empty extends StatelessWidget{const _Empty({required this.icon,required this.title,required this.text});final IconData icon;final String title,text;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.symmetric(horizontal:24,vertical:44),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:38,color:Theme.of(context).colorScheme.primary),const SizedBox(height:12),Text(title,style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:4),Text(text,textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodySmall)]));}
Color _color(BuildContext c,WorkStatus s)=>s==WorkStatus.completed?Colors.green:s==WorkStatus.failed||s==WorkStatus.cancelled?Theme.of(c).colorScheme.error:Colors.amber.shade800;
String _status(WorkStatus value)=>value.name.replaceAllMapped(RegExp(r'([A-Z])'),(m)=>' ${m.group(1)!.toLowerCase()}');
